                let b := byte(i, v) // Extract i-th byte from left
                let pos := shl(1, i) // Output position = i * 2
                mstore8(add(o, pos), byte(shr(4, b), table)) // High nibble → ASCII
                mstore8(add(o, add(pos, 1)), byte(and(b, 0xf), table)) // Low nibble → ASCII
