        assembly {
            result := mload(0x40)

            switch value
            case 0 {
                mstore(0x40, add(result, 0x40)) // 32 (length slot) + 1 (data) = 33, round to 64
                mstore(result, 1) // length = 1
                mstore8(add(result, 32), 0x30) // '0'
